// 6. ПУБЛІЧНЕ API
// ============================================

/**
 * Розумний NLP-пошук продуктів.
 * @param {string} query - пошуковий запит користувача
 * @param {number} limit - максимальна кількість результатів
 * @returns {Array} масив продуктів, відсортований за релевантністю
 */
export function smartSearch(query, limit = 8) {
  if (!query || normalize(query).length < 2) return [];

  const nlpData = preprocessQuery(query);
  const fuse = getFuse();

  // Формуємо пошуковий запит з урахуванням токенів, стемів та синонімів
  const searchTerms = Array.from(new Set([...nlpData.tokens, ...nlpData.stems]));
  const extraSynonyms = expandWithSynonyms(searchTerms, nlpData.raw);

  // Об'єднуємо унікальні слова для пошуку
  const cleanQueryString = Array.from(new Set([...searchTerms, ...extraSynonyms])).join(' ');

  // Основний пошук через Fuse.js
  let results = fuse.search(cleanQueryString, { limit: limit * 2 });

  // Резервний пошук тільки за введеними токенами, якщо розширений запит дав 0 результатів
  if (results.length === 0 && nlpData.tokens.length > 1) {
    results = fuse.search(nlpData.tokens.join(' '), { limit: limit * 2 });
  }

  // Перевірка точних збігів кодів/моделей (наприклад: "V1/50", "v1-50", "v150")
  const codeNorm = normalize(query).replace(/[\s/\-_]/g, '');
  const exactCodeMatches = getAllProducts().filter((p) => {
    const idNorm = p.id.toLowerCase().replace(/[\s/\-_]/g, '');
    const titleNorm = p.title.toLowerCase().replace(/[\s/\-_]/g, '');
    return idNorm === codeNorm || idNorm.includes(codeNorm) || titleNorm.includes(codeNorm);
  });

  // Дедуплікація та ранжування
  const seen = new Set();
  const combined = [];

  // 1. Спочатку додаємо точні збіги кодів
  exactCodeMatches.forEach((p) => {
    if (!seen.has(p.id)) {
      seen.add(p.id);
      combined.push(p);
    }
  });

  // 2. Потім додаємо решту результатів з Fuse
  results.forEach((r) => {
    if (!seen.has(r.item.id)) {
      seen.add(r.item.id);
      combined.push(r.item);
    }
  });

  return combined.slice(0, limit);
}

export function smartSearchAll(query) {
  return smartSearch(query, 100);
}

export function getSuggestions(query, limit = 5) {
  return smartSearch(query, limit).map((p) => p.title);
}

export function rebuildSearchIndex() {
  getFuse(true);
}
